+export interface RetryOptions {
+  attempts: number;
+  baseDelayMs: number;
+}
+
+/** The docs promise at most 30 s between attempts. */
+const MAX_DELAY_MS = 30_000;
+
+export async function withRetry(run: () => Promise<Response>, opts: RetryOptions): Promise<Response> {
+  for (let i = 0; i < opts.attempts; i++) {
+    const res = await run().catch(() => null);
+    if (res && res.ok) return res;
+    const backoff = Math.min(MAX_DELAY_MS, opts.baseDelayMs * 2 ** i);
+    // Full jitter: clients that failed together do not retry in lockstep.
+    await sleep(Math.random() * backoff);
+  }
+  throw new Error('request failed after retries');
+}
